, "year_opened": "1910", "official_website_url": "https://gullanegolfclub.com/gullane-no-3/", "course_status": "active", "access_type": "visitors_welcome", "map_ready": "1", "show_on_map": "1", "map_display_reason": "verified_layout_location", "ranking_provider": "", "ranking_list": "", "ranking_position": "", "major_collection": "", "featured_partner": "0", "verification_status": "verified_official_and_layout_location", "primary_source": "Official Gullane No. 3 course page and visitor guide", "source_url": "https://gullanegolfclub.com/gullane-no-3/", "source_checked_at": "2026-10-18T00:00:00.000Z", "coordinate_source": "Layout-specific mapped Gullane No. 3 location", "coordinate_verified_at": "2026-10-18T00:00:00.000Z", "notes": "INSERT under existing Gullane Golf Club ID. Official course material confirms opened 1910, 18 holes, 5,134 yards and par 67. The club states there was no official designer: the course was overseen by committee and built by greenkeeper William Logan and his team. County is recorded as Lothian to match the existing Gullane parent records; the official postal address is in East Lothian.", "record_action": "INSERT"}]$records$::jsonb)
 LOOP
  SELECT count(*),min(id) INTO matched_count,existing_id FROM courses WHERE hl_course_id=r->>'hl_course_id';
  IF matched_count>1 THEN RAISE EXCEPTION 'Duplicate course ID: %',r->>'hl_course_id'; END IF;
  IF existing_id IS NULL AND r->>'record_action'='UPDATE_EXISTING' THEN
   RAISE EXCEPTION 'Expected existing course missing: %',r->>'hl_course_id';
  END IF;
  IF existing_id IS NOT NULL AND EXISTS (
   SELECT 1 FROM courses WHERE id=existing_id AND (country IS DISTINCT FROM r->>'country' OR (hl_club_id IS NOT NULL AND hl_club_id<>r->>'hl_club_id'))
  ) THEN RAISE EXCEPTION 'Identity conflict: %',r->>'hl_course_id'; END IF;
  IF existing_id IS NULL THEN
   IF EXISTS (SELECT 1 FROM courses WHERE lower(country)=lower(r->>'country') AND (
    lower(coalesce(display_name,name))=lower(r->>'display_name') OR lower(name)=lower(r->>'display_name')
   )) THEN RAISE EXCEPTION 'Possible existing course under different ID: %',r->>'display_name'; END IF;
   INSERT INTO courses(name,club_name,display_name,hl_course_id,hl_club_id,city,county,region,country,latitude,longitude,holes,par,website,course_status)
   VALUES(coalesce(nullif(r->>'course_name',''),r->>'club_name'),r->>'club_name',r->>'display_name',r->>'hl_course_id',r->>'hl_club_id',r->>'town_city',r->>'county',r->>'region',r->>'country',(r->>'latitude')::double precision,(r->>'longitude')::double precision,(r->>'holes')::integer,(r->>'par')::integer,r->>'official_website_url',r->>'course_status')
   RETURNING id INTO existing_id;
  ELSE
   UPDATE courses SET
    name=coalesce(nullif(r->>'course_name',''),r->>'club_name'),club_name=r->>'club_name',display_name=r->>'display_name',
    hl_club_id=r->>'hl_club_id',city=r->>'town_city',county=r->>'county',region=r->>'region',
    latitude=(r->>'latitude')::double precision,longitude=(r->>'longitude')::double precision,
    holes=(r->>'holes')::integer,par=(r->>'par')::integer,
    website=r->>'official_website_url',course_status=r->>'course_status'
   WHERE id=existing_id;
  END IF;
  INSERT INTO course_update_sources VALUES('missing-courses-20261025',r->>'hl_course_id',r)
  ON CONFLICT(source_key,hl_course_id) DO UPDATE SET source_record=EXCLUDED.source_record;
 END LOOP;
END $delta$;
